// Refuse instead of throwing: n8n answers 200 when a flow fails before its Respond node,
// so a missing setting would count every event as delivered.
try {
  const crypto = require('crypto');
  const h = $input.first().json.headers;
  const secret = $env.MUELLE_WHSEC;
  if (!secret) return [{ json: { refused: "Set MUELLE_WHSEC in n8n to this connection's signing secret" } }];
  const body = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
  const key = Buffer.from(secret.replace(/^whsec_/, ''), 'base64');
  const expected = Buffer.from('v1,' + crypto.createHmac('sha256', key)
    .update(`${h['webhook-id']}.${h['webhook-timestamp']}.${body}`).digest('base64'));
  const ok = String(h['webhook-signature'] || '').split(' ').some((s) => {
    const given = Buffer.from(s);
    return given.length === expected.length && crypto.timingSafeEqual(given, expected);
  });
  if (!ok || Math.abs(Date.now() / 1000 - Number(h['webhook-timestamp'])) > 300) {
    return [{ json: { refused: 'Bad signature' } }];
  }
  const event = JSON.parse(body);
  // Delivery is at-least-once: a retry repeats webhook-id. Answer it, but do the work once.
  const store = $getWorkflowStaticData('global');
  const seen = store.seenIds || [];
  if (seen.includes(h['webhook-id'])) return [{ json: { duplicate: true } }];
  store.seenIds = [...seen.slice(-999), h['webhook-id']];
  return [{ json: event }];
} catch (e) {
  return [{ json: { refused: `Cannot verify: ${e.message}` } }];
}
